class Solution { private val visited=hashSetOf<String>();private val trail=StringBuilder();private var k=0;private var n=0;fun crackSafe(n:Int,k:Int):String{this.n=n;this.k=k;val start="0".repeat(n-1);dfs(start);return start+trail.reverse()};private fun dfs(node:String){for(digit in 0 until k){val edge=node+digit;if(visited.add(edge)){dfs(edge.substring(edge.length-(n-1)));trail.append(digit)}}} }
